"""
    Calculates changes in accumulation/distribution line.
    A/D = ((Close - Low) - (High - Close))/(High - Low)

    Args:
        open: Float representing exchange rate at the beginning of an interval
        high: Float representing the highest exchange rate during the interval
        low: Float respresenting the lowest exchange rate during the interval
        close: Float representing the exchange rate at the end of an interval
        volume: Float representing the number of trades during the interval

    Returns:
        Float representing the change in accumulation/distribution
    """
def calculate_accumulation_distribution(
    open: Any, high: Any, low: Any, close: Any, volume: Any
) -> object {
    if (high == low) {
        return 0;
    }
    return ((((2 * close) - low - high) / (high - low)) * volume);
}

"""
    Determines whether a [x,y] point is strictly inside a convex polygon
    defined as an ordered list of [x,y] points.

    :param point: the point to check
    :param polygon: the polygon
    :return: True if point is inside polygon, False otherwise
    """
def point_in_polygon(point: Any, polygon: Any) -> object {
    x = point[0];
    y = point[1];
    n = len(polygon);
    inside = False;
    xints = 0.0;
    (p1x, p1y) = polygon[0];
    for i in range((n + 1)) {
        (p2x, p2y) = polygon[(i % n)];
        if (y > min(p1y, p2y)) {
            if (y <= max(p1y, p2y)) {
                if (x <= max(p1x, p2x)) {
                    if (p1y != p2y) {
                        xints = (((y - p1y) * (p2x - p1x)) / (p2y - p1y)) + p1x;
                    }
                    if ((p1x == p2x) or (x <= xints)) {
                        inside = not inside;
                    }
                }
            }
        }
        (p1x, p1y) = (p2x, p2y);
    }
    return inside;
}

"""bubble sort"""
def bubbleSort(unsort: list) -> list {
    arr = unsort.copy();
    last = len(arr) - 1;
    for i in range(0, last) {
        for j in range(0, (last - i)) {
            if (arr[j] > arr[(j + 1)]) {
                (arr[j], arr[(j + 1)]) = (arr[(j + 1)], arr[j]);
            }
        }
    }
    return arr;
}

