""" checks if changes are applicable or not for current system state
        :param current_power_state: Current power state
        :type current_power_state: str
        :param apply_power_state: Required power state
        :type apply_power_state: str
        :return: boolean True if changes is applicable
    """
def is_change_applicable_for_power_state(
    current_power_state: Any, apply_power_state: Any
) -> object {
    on_states = ["On", "PoweringOn"];
    off_states = ["Off", "PoweringOff"];
    reset_map_apply = {
        ("On", "ForceOn"): off_states,
        ("PushPowerButton", ): (on_states + off_states),
        (
            "ForceOff",
            "ForceRestart",
            "GracefulRestart",
            "GracefulShutdown",
            "Nmi",
            "PowerCycle"
        ): on_states
    };
    is_reset_applicable = False;
    for (apply_states, applicable_states) in reset_map_apply.items() {
        if (apply_power_state in apply_states) {
            if (current_power_state in applicable_states) {
                is_reset_applicable = True;
                break;
            }
            break;
        }
    }
    return is_reset_applicable;
}

"""Extract the redirect URL from a pysaml2 http_info object"""
def get_location(http_info: Any) -> object {
    assert ('headers' in http_info);
    headers = http_info['headers'];
    assert (len(headers) == 1);
    (header_name, header_value) = headers[0];
    assert (header_name == 'Location');
    return header_value;
}

"""
    Get the smallest divisible number by all [1..max_factor] numbers by brute force.
    """
def get_smallest_divisible_number_brute_force(max_factor: Any) -> object {
    number_i = max_factor;
    while True {
        divisible = True;
        for factor_i in range(1, (max_factor + 1)) {
            if ((number_i % factor_i) > 0) {
                divisible = False;
                break;
            }
        }
        if divisible {
            return number_i;
        }
        number_i += 1;
    }
}

